import * as assert from 'assert'
import * as fs from 'node:fs'
import { test } from 'bun:test'
import { INPAGE_SCRIPTS } from '../../app/ts/config/injectedScripts.js'
import { getManifestV2DocumentStartScriptPath, getPageWorldScriptPaths } from '../../app/ts/utils/contentScriptInjectionArtifacts.js'

test('every injected script is emitted from an app/inpage/ts source', () => {
	// The compatibility-mode variants are generated by the bundler from the default provider and document-start sources.
	const injectedScripts = [...Object.values(INPAGE_SCRIPTS), ...getPageWorldScriptPaths(false), getManifestV2DocumentStartScriptPath(false)]
	for (const file of injectedScripts) {
		const sourcePath = file.replace(/^\/?inpage\/js\//, 'app/inpage/ts/').replace(/\.js$/, '.ts')
		assert.ok(fs.existsSync(sourcePath), `${ file } has no source at ${ sourcePath }`)
	}
})

test('native hosting adds no web-accessible host or preparation scripts', () => {
	for (const manifestPath of ['app/manifestV3.json', 'app/manifestV2.json']) {
		const manifestSource = fs.readFileSync(manifestPath, 'utf8')
		assert.equal(manifestSource.includes('gnosisSafeAppsHostBootstrap'), false)
		assert.equal(manifestSource.includes('prepareGnosisSafeApp'), false)
		assert.equal(manifestSource.includes('inpage/*'), false)
	}
})
